('RS','sr','rs-serbian-orthodox-church','2026-01-01',null,array[]::text[],'Свети мученик Бонифатије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-02',null,array[]::text[],'Претпразништво телесног Рођења Господа нашег Исуса Христа. Свети свештеномученик Игнатије Богоносац. И Свети отац наш Данило II, Архиепископ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-03',null,array[]::text[],'Претпразништво Рођења Христовог. Света мученица Јулијана, која беше у Никомидији. Субота пред Рођење Христово.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-04',null,array[]::text[],'НЕДЕЉА ПРЕД РОЂЕЊЕМ ХРИСТОВИМ - СВЕТИХ ОТАЦА
Претпразништво Рођења Христовог. Света великомученица Анастасија Узорешитељница – њој службу појемо на повечерју. И Свети Никифор Лепрозни.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-05',null,array[]::text[],'Претпразништво телесног Рођења Господа нашег Исуса Христа. Светих 10 мученика Критских. Преподобни и равноапостолни отац наш Наум Охридски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-06',null,array[]::text[],'Претпразништво Рођења Христовог. Света преподобномученица Евгенија. Бадњи дан.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-07',null,array[]::text[],'РОЂЕЊЕ ПО ТЕЛУ ГОСПОДА БОГА И СПАСА НАШЕГ ИСУСА ХРИСТА - БОЖИЋ',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-08',null,array[]::text[],'Сабор Пресвете Богородице и Светог Јосифа Обручника. Свети свештеномученик Евтимије, Епископ Сардски - њему службу појемо на повечерју 27. децембра.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-09',null,array[]::text[],'Свети апостол, првомученик и архиђакон Стефан. И преподобни отац наш и исповедник Теодор Начертани и брат његов Теофан, писац /канона/. Свети свештеномученик Евтимије, Епископ Сардски - њему службу појемо на повечерју, од 26. децембра.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-10',null,array[]::text[],'Светих 20.000 мученика у Никомидији спаљених. Субота по Рођењу Христовом.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-11',null,array[]::text[],'НЕДЕЉА ПО РОЂЕЊУ ХРИСТОВОМ - СВЕТИХ БОГООТАЦА
Светог Јосифа Обручника, Цара Давида и Јакова, брата Господњег.
Светих 14.000 младенаца (=деце, беба) за Христа побијених у Витлејему од Ирода - њима службу појемо на повечерју. И преподобни отац наш Маркел, игуман манастира неспавајућих.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-12',null,array[]::text[],'Света мученица Анисија. И преподобна мати наша Меланија Римљанка - њој појемо службу од 31. о. м. И преподобни Зотик Презвитер - њему службу појемо на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-13',null,array[]::text[],'Оданије Празника Телесног рођења Господа Бога и Спаса нашег Исуса Христа. Свети Доситеј Загребачки, Исповедник.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-14',null,array[]::text[],'Телесно обрезање Господа и Бога и Спаса нашега Исуса Христа. И Свети отац наш Василије Велики, Архиепископ Кесарије Кападокијске.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-15',null,array[]::text[],'Претпразништво Богојављења. Свети отац наш Силвестар, Папа Римски. Преподобни отац наш Серафим Саровски, Чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-16',null,array[]::text[],'Претпразништво Богојављења. Свети пророк Малахија. И мученик Гордије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-17',null,array[]::text[],'Претпразништво Богојављења. Сабор Светих 70 Апостола. И преподобни Теоктист, игуман обитељи у Куми Сикилијској. И Свети Евстатије, Архиепископ Српски. Субота пред Богојављење.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-18',null,array[]::text[],'НЕДЕЉА ТРИДЕСЕТ ДРУГА ПО ПЕДЕСЕТНИЦИ Претпразништво Богојављења. Свети мученици Теопемт и Теона. И преподобна Синклитикија. Недеља пред Богојављење.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-19',null,array[]::text[],'СВЕТО БОГОЈАВЉЕЊЕ ГОСПОДА БОГА И СПАСИТЕЉА НАШЕГ ИСУСА ХРИСТА.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-20',null,array[]::text[],'Попразништво Богојављења. Сабор Светог славног Пророка и Претече и Kрститеља Јована.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-21',null,array[]::text[],'Попразништво Богојављења. Преподобни отац наш Георгије Хозевит. И преподобна Доминика. Свети Григорије Охридски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-22',null,array[]::text[],'Попразништво Богојављења. Свети мученик Полиевкт. Свети Филип, Митрополит Московски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-23',null,array[]::text[],'Попразништво Богојављења. Свети отац наш Григорије, Епископ Ниски. И преподобни Доментијан Митилински. И Свети отац наш Маркијан, презвитер и старешина Велике цркве у Цариграду - њему службу појати на повечерју. Свети Теофан Затворник Вишински, Епископ Владимирски и Суздаљски. Свети мученици Бачки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-24',null,array[]::text[],'Попразништво Богојављења. Преподобни отац наш Теодосије Велики, зачетник општежића. Субота по Богојављењу.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-25',null,array[]::text[],'НЕДЕЉА ТРИДЕСЕТ ТРЕЋА ПО ПЕДЕСЕТНИЦИ. Попразништво Богојављења. Света мученица Татијана. Спомен Пресвете Владарке наше Богородице, у част јављања Њене чудотворне иконе, назване Млекопитатељица. Недеља по Богојављењу.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-26',null,array[]::text[],'Оданије Празника Богојављења (у нашој помесној Цркви). Свети мученици Ермил и Стратоник – њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-27',null,array[]::text[],'Свети отац наш Сава, први Архиепископ и учитељ Српски. Спомен погибли, преподобних отаца наших Синајских и Раитских - њима службу појати на повечерју 15.1.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-28',null,array[]::text[],'Преподобни оци наши Павле Тивејски и Јован Колибар. И спомен погибли, преподобних отаца наших Синајских и Раитских - њима службу појати на повечерју. Преподобни отац наш Гаврило Лесновски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-29',null,array[]::text[],'Поклоњење часним веригама Светог и свехвалног Апостола Петра. И преподобни и богоносни отац наш Ромило Раванички, Синаит.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-30',null,array[]::text[],'Преподобни и богоносни отац наш Антоније Велики.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-01-31',null,array[]::text[],'Свети оци наши, Атанасије и Кирило, Архиепископи Александријски. Свети отац наш, Архиепископ Максим, бивши деспот српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-01',null,array[]::text[],'НЕДЕЉА У КОЈУ СЕ ЧИТА СВЕШТЕНО И СВЕТО ЈЕВАНЂЕЉЕ О ЦАРИНИКУ И ФАРИСЕЈУ Преподобни отац наш Макарије Египатски. И Свети отац наш Марко, Мирополит Ефески, Исповедник – њима службе појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-02',null,array[]::text[],'Преподобни и богоносни отац наш Јефтимије Велики.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-03',null,array[]::text[],'Преподобни отац наш Максим Исповедник. И Свети мученик Неофит. И Свети мученици : Евгеније, Кандида, Валеријана и Акиле - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-04',null,array[]::text[],'Свети апостол Тимотеј. И Свети преподобномученик Анастасије Персијанац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-05',null,array[]::text[],'Свети свештеномученик Климент Анкирски. И Свети мученик Агатангел.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-06',null,array[]::text[],'Преподобна мати наша Ксенија Римљаника. Блажена Ксенија Петровградска.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-07',null,array[]::text[],'Свети отац наш Григорије Богослов, Архиепископ Цариградски. Свети преподобномученик Григорије Пећки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-08',null,array[]::text[],'НЕДЕЉА У КОЈУ СЕ ЧИТА СВЕШТЕНО И СВЕТО ЈЕВАНЂЕЉЕ О ЗАБЛУДЕЛОМ СИНУ. Преподобни отац наш Ксенофонт и породица његова – њима службу појати на повечерију 25.1.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-09',null,array[]::text[],'Пренос моштију Светог оца нашег Јована Златоустог, Архиепископ Цариградски. Свети Данило, Епископ карловачки и плашчански.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-10',null,array[]::text[],'Преподобни отац наш Јефрем Сирин.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-11',null,array[]::text[],'Пренос моштију Светог свештеномученика Игнатија Богоносца.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-12',null,array[]::text[],'Међу Светим оцима нашим и великим јерарсима, Василије Велики, Григорије Богослов и Јован Златоусти. И Свети свештеномученик Иполит, Папа Римски - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-13',null,array[]::text[],'Предпразништво Сретења Господа Бога и Спаса нашега Исуса Христа. Свети чудотворци и бесребреници Кир и Јован. И Свети мученик Трифун.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-14',null,array[]::text[],'Претпразништво Сретења Господа нашега Исуса Христа. И Свети мученик Трифун – службе се поју претходни дан.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-15',null,array[]::text[],'НЕДЕЉА У КОЈУ СЕ ЧИТА СВЕШТЕНО И СВЕТО ЈЕВАНЂЕЉЕ О СТРАШНОМ СУДУ „МЕСОПУСНА НЕДЕЉА“ СРЕТЕЊЕ ГОСПОДА БОГА И СПАСИТЕЉА НАШЕГА ИСУСА ХРИСТА.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-16',null,array[]::text[],'Сирна седмица. Попразништво Сретења Господњег. Свети и праведни Симеон Богопримац и Ана пророчица. И Свети отац наш Јаков, Архиепископ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-17',null,array[]::text[],'Сирна седмица. Попразништво Сретења Господњег. Преподобни отац наш Исидор Пелусиот.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-18',null,array[]::text[],'Сирна седмица. Попразништво Сретења Господњег. Света мученица Агатија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-19',null,array[]::text[],'Сирна седмица Оданије Празника Сретења Господњега. Свети отац наш Вукол, Епископ Смирски. И Свети отац наш, равноапостолни Фотије, Патријарх Цариградски – њима службе појати на повечерију.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-20',null,array[]::text[],'Сирна седмица. Свети отац наш Партеније, Епископ Ламсакијски. И преподобни отац наш Лука Јеладски – службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-21',null,array[]::text[],'Сирна седмица. СУБОТА „ СИРНА“ У КОЈОЈ СЕ ПРОСЛАВЉА УСПОМЕНА НА СВЕТЕ, ПРЕПОДОБНЕ И БОГОНОСНЕ ОЦЕ НАШЕ КОЈИ СУ ЗАСИЈАЛИ ПОСТОМ. И великомученик Теодор Стратилат. И пророк Захарија Срповидац – њима службу појати на повечерју. И Свети отац наш Сава II Архиепископ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-22',null,array[]::text[],'НЕДЕЉА У КОЈОЈ СЕ СЕЋАМО ИЗГНАЊА АДАМОВОГ - „СИРОПУСНА НЕДЕЉА“ - Свети мученик Никифор - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-02-23',null,array[]::text[],'Прва седмица поста. Свети мученик Харалампије.',null,null,'Српска Православна Црква, Типик 2026',true),
