('RS','sr','rs-serbian-orthodox-church','2026-05-02',null,array[]::text[],'Трећа седмица по Пасхи. Преподобни отац наш Јован, из Старе лавре ( Харитонове у Палестини ). Блажена Матрона Московска.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-03',null,array[]::text[],'НЕДЕЉА ЧЕТВРТА ПО ПАСХИ - РАСЛАБЉЕНОГА - Преподобни отац наш Теодор Трихенски. И Свети отац наш Николај, Епископ Жички. И Преподобни отац наш Јоасаф, ( Српски ) Метеоритски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-04',null,array[]::text[],'Четврта семица по Пасхи. Свети свештеномученик Јануарије и други са њиме пострадали. И Свети свештеномученик Теодор из Пергије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-05',null,array[]::text[],'Четврта седмица по Пасхи. Свети отац наш Теодор Сикеот, Епископ Анастасиупољски. И Свети свештеномученик Платон, Епископ Бањалучки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-06',null,array[]::text[],'Четврта седмица по Пасхи. ПРЕПОЛОВЉЕЊЕ ПЕДЕСЕТНИЦЕ Свети славни великомученик, победоносац и чудотворац Георгије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-07',null,array[]::text[],'Четврта седмица по Пасхи. Свети мученик Сава Стратилат. И Свети отац наш Сава II, Митрополит Алба Јулије, у Ердељу. Свети свештеномученик Бранко, парох вељунски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-08',null,array[]::text[],'Четврта седмица по Пасхи. Свети и свехвални Апостол и Јеванђелист Марко.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-09',null,array[]::text[],'Четврта седмица по Пасхи. Свети свештеномученик Василије, Епископ Амасијски. Пренос моштију преподобног оца нашег Јоаникија Девичког.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-10',null,array[]::text[],'НЕДЕЉА ПЕТА ПО ПАСХИ - САМАРЈАНКЕ Свети свештеномученик Симеон, сродник Господњи - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-11',null,array[]::text[],'Пета седмица по Пасхи. Свети апостоли Јасон и Сосипатар. И мученици Дад, Максим и Квинтилијан.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-12',null,array[]::text[],'Пета седмица по Пасхи. Свети отац наш Василије, Митрополит Захумски, који нетљено почива у Острогу. Свети мученик Василије, пекар из Пећи. Светих девет мученика пострадалих у Кизику - њима службу појати на повечерју. И преподобни Мемнон Чудотворац - њему службу појати на повечерју 30. о.м.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-13',null,array[]::text[],'Пета седмица по Пасхи. Оданије Празника Преполовљења Педесетнице. Свети и свехвали апостол Јаков / Заведејев /, брат апостола Јована Богослова.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-14',null,array[]::text[],'Пета седмица по Пасхи. Свети пророк Јеремија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-15',null,array[]::text[],'Пета седмица по Пасхи. Свети отац наш Атанасије Велики, Архиепископ Александријски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-16',null,array[]::text[],'Пета седмица по Пасхи. Свети мученици Тимотеј и Мавра.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-17',null,array[]::text[],'НЕДЕЉА ШЕСТА ПО ПАСХИ - О СЛЕПОРОЂЕНОМ Света преподобномученица Пелагија - њој службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-18',null,array[]::text[],'Шеста седмица по Пасхи. Света и славна мученица Ирина.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-19',null,array[]::text[],'Шеста седмица по Пасхи. Пренос часних моштију, Светог оца нашег Саве, првог Архиепископа и просветитеља Српског, из града Трнова у славну Лавру Милешевску, Вазнесења Спасовог. Свети, праведни и многострадални Јов.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-20',null,array[]::text[],'Шеста седмица по Пасхи. ОДАНИЈЕ ПРАЗНИКА ПАСХЕ. Спомен јављања (појаве) часног и животворног Крста на небу у светоме граду Јерусалиму над Голготом, протежући се до горе Маслинске, у трећи час дана, у време Цара Констанција, сина Константина Великог и Патријарха Кирила - службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-21',null,array[]::text[],'Шеста седмица по Пасхи. ВАЗНЕСЕЊЕ ГОСПОДА БОГА И СПАСА НАШЕГА ИСУСА ХРИСТА. Свети и прехвални Апостол и Јеванђелист Јован Богослов. Преподобни отац наш Арсеније Велики – њему службу појати на повечерју. Свети свештеномученик Недељко Раковички.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-22',null,array[]::text[],'Шеста седмица по Пасхи. Пренос часних моштију Светог оца нашег Николаја Чудотворца, из Мире Ликијске у Бари. Пророк Исаија - њему службу појати на повечерју. Свети мученик Христофор. Чудотворна икона Пресвете Богородице, названа Пећка.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-23',null,array[]::text[],'Шеста седмица по Пасхи. Свети апостол Симон Зилот. Свети мученик Христофор - њему службу појати на повечерју, од 9.5.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-24',null,array[]::text[],'НЕДЕЉА СЕДМА ПО ПАСХИ - САБОР СВЕТИХ 318 БОГОНОСНИХ ОТАЦА (ПРВОГ ВАСЕЉЕНСКОГ САБОРА) У НИКЕЈИ. Свети равноапостолни Методије и Кирило, учитељи словенски. Свети отац наш Никодим, Архиепископ Пећки и Српски - њему се служба поје 12.5. Свети свештеномученик Мокије - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-25',null,array[]::text[],'Седма седмица по Пасхи. Свети отац наш Епифаније, Епископ Кипарски. И Свети отац наш Герман, Патријарх Цариградског. И Свети отац наш Никодим, Архиепископ Пећки и Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-26',null,array[]::text[],'Седма седмица по Пасхи. Свети мученица Гликерија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-27',null,array[]::text[],'Седма седмица по Пасхи. Свети мученик Исидор, пострадао на острву Хиосу.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-28',null,array[]::text[],'Седма седмица по Пасхи. Преподобни Пахомије Велики. И Свети Ахилије, Епископ Лариски - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-29',null,array[]::text[],'Седма седмица по Пасхи. ОДАНИЈЕ ПРАЗНИКА ВАЗНЕСЕЊА СПАСОВОГ. Преподобни отац наш Теодор Освећени, ученик преп. Пахомија Великог – њему службу појати на повечерју. И Свети свештеномученик Теодор, Епископ Вршачки. И мученик Вукашин. И Свети Викентије. И Свети мученици Сурдулички.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-30',null,array[]::text[],'Седма седмица по Пасхи. Свети апостол Андроник и они са њиме пострадали / блажена Јунија / - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-05-31',null,array[]::text[],'ПРАЗНИК СИЛАСКА СВЕТОГ ДУХА НА АПОСТОЛЕ - ПЕДЕСЕТНИЦА Свети мученик Теодот Анкирски. И свети мученици Петар и Дионисије, и они са њима пострадали. И светих седам девојака мученица.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-01',null,array[]::text[],'ПОНЕДЕЉАК ПЕДЕСЕТНИЦЕ - ДАН СВЕТОГА ДУХА. Свети свештеномученик Патрикије, Епископ Пруски, и са њим три презвитера.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-02',null,array[]::text[],'Седмица по Педесетници. Свети мученик Талалеј. Преподобни отац наш Стефан Пиперски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-03',null,array[]::text[],'Седмица по Педесетници. Свети цар Константин Велики и мајка његова царица Јелена. Преподобна мати наша Јелена Дечанска.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-04',null,array[]::text[],'Седмица по Педесетници. Свети мученик Василиск. Свети великомученик кнез српски Јован Владимир, чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-05',null,array[]::text[],'Седмица по Педесетници. Треће обретење ( проналажење ) часне главе Светог славног Пророка, Претече и Крститеља Јована ( од 25.5.). Свети отац наш Михаило Исповедник, Епископ Синадски - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-06',null,array[]::text[],'Седмица по Педесетници. ОДАНИЈЕ ПРАЗНИКА СИЛАСКА СВЕТОГ ДУХА НА АПОСТОЛЕ - ПЕДЕСЕТНИЦЕ. Преподобни отац наш Симеон Столпник, Дивногорац. - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-07',null,array[]::text[],'НЕДЕЉА ПРВА ПО ПЕДЕСЕТНИЦИ - СВИХ СВЕТИХ. Треће обретење ( проналажење ) часне главе Светог славног Пророка, Претече и Крститеља Јована - службу појати у петак 23.5. Свети мученици Пивски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-08',null,array[]::text[],'Почетак поста Светих Апостола. Свети апостол Карп, један од Седамдесеторице.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-09',null,array[]::text[],'Свети свештеномученик Терапонт Преподобни Јован Рус.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-10',null,array[]::text[],'Свети отац наш Никита, Епископ Халкидонски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-11',null,array[]::text[],'Света преподобномученица Теодосија, девојка. Свети Лука, Архиепископ Симферопољски и Кримски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-12',null,array[]::text[],'Преподобни отац наш Исакије Далматски. Преподобни Варлаам Хутински.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-13',null,array[]::text[],'Свети апостол Јерма. И Свети мученик Ермије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-14',null,array[]::text[],'НЕДЕЉА ДРУГА ПО ПЕДЕСЕТНИЦИ - СВИ СВЕТИ КОЈИ СУ У ЗЕМЉИ СРПСКОЈ ПРОСИЈАЛИ. Свети Јустин Мученик и Философ, и други мученик Јустин и они са њима пострадали – њима службу појати на повечерју. И преподобни отац наш Јустин Ћелијски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-15',null,array[]::text[],'Свети отац наш Никифор Исповедник, Патријарх Цариградски. И Свети свештеномученик Еразмо Охридски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-16',null,array[]::text[],'Свети мученик Лукилијан и они са њиме пострадали.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-17',null,array[]::text[],'Свети отац наш Митрофан, Патријарх Цариградски. Свети Јоаникије Црногорско-приморски. И Свети свештеномученик Ђорђе ( Богић ).',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-18',null,array[]::text[],'Свети отац наш Доротеј, Епископ Тирски. И преподобни отац наш Петар Коришки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-19',null,array[]::text[],'Преподобни отац наш Висарион Чудотворац. И преподобни отац наш Иларион, игуман Далматски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-20',null,array[]::text[],'Свети свештеномученик Теодот, Епископ Анкирски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-21',null,array[]::text[],'НЕДЕЉА ТРЕЋА ПО ПЕДЕСЕТНИЦИ. Свети великомученик Теодор Стратилат.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-22',null,array[]::text[],'Свети отац наш Кирило, Архиепископ Александријски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-23',null,array[]::text[],'Свети свештемомученик Тимотеј, Епископ Пруски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-24',null,array[]::text[],'Свети и свехвални апостоли Вартоломеј и Варнава. Празновање Пресвете Богородице у част њене чудотворне иконе, назване Д ост0йно є4сть: у спомен на чудо архангела Гаврила, који је изрекао и написао на камену ову песму, у близини Кареје, на Светој гори.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-25',null,array[]::text[],'Преподобни отац наш Онуфрије Велики. И преподобни отац наш Петар Атонски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-26',null,array[]::text[],'Света мученица Акилина. И Свети отац наш Трифилије, Епископ Левкосије кипарске. Свети свештеномученици Житомислићки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-27',null,array[]::text[],'Свети пророк Јелисеј. И Свети отац наш Методије, Патријарх Цариградски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-28',null,array[]::text[],'НЕДЕЉА ЧЕТВРТА ПО ПЕДЕСЕТНИЦИ. Свети блажени великомученик кнез Лазар, бивши самодржац српских земаља. И Свети мученици пострадали за веру Христову од времена Светог великомученика кнеза Лазара до данас. Свети пророк Амос - њему службу појати на повечерју. Свети отац наш Јефрем, Патријарх Српски - њему службу појати 16.6.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-29',null,array[]::text[],'Свети отац наш Тихон, Епископ Аматунски, Чудотворац. И Свети отац наш Јефрем, Патријарх Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-06-30',null,array[]::text[],'Свети мученици Мануил, Савел и Исмаил.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-01',null,array[]::text[],'Свети мученик Леонтије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-02',null,array[]::text[],'Свети и свехвални апостол Јуда, брат Господњи. Преподобнн отац наш Пајсије Велики. Свети Јован, Архиепископ Западноамерички и Санфранциски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-03',null,array[]::text[],'Свети свештеномученик Методије, Епископ Патарски. И Преподобнн отац наш Наум Охридски, Чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-04',null,array[]::text[],'Свети мученик Јулијан Тарсијски. Преподобна мати наша Анастасија, мајка Светога Саве.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-05',null,array[]::text[],'НЕДЕЉА ПЕТА ПО ПЕДЕСЕТНИЦИ. Свети свештеномученик Евсевије, Епископ Самосатски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-06',null,array[]::text[],'Свети мученица Агрипина.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-07',null,array[]::text[],'Рођење часног славног Пророка, Претече и Крститеља Јована. Свети Никита, Епископ Ремезијански.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-08',null,array[]::text[],'Света мученица Февронија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-09',null,array[]::text[],'Преподобни отац наш Давид Солунски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-10',null,array[]::text[],'Преподобни отац наш Сампсон Странопримац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-11',null,array[]::text[],'Пренос моштију Светих бесребреника и чудотвораца Кира и Јована. Спомен Светих свештеномученика епархије Милешевске. И спомен Светог свештеномученика Нестора игумана милешевског.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-12',null,array[]::text[],'НЕДЕЉА ШЕСТА ПО ПЕДЕСЕТНИЦИ. Свети славни, свехвални и врховни апостоли Петар и Павле. Пренос моштију Светог Стефана Уроша III ( Дечанског ) из Звечена у своју обитељ. Пренос моштију Светог Петра Коришког из Кориша у манастир Црна Река. Преподобни Пајсије Светогорац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-13',null,array[]::text[],'Сабор свете славне и свехвалне дванаесторице апостола. Света Деца мученици Јастребарски и Сисачки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-14',null,array[]::text[],'Свети бесребреници и чудотворци Козма и Дамјан, родом из Рима.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-15',null,array[]::text[],'Полагање часне ризе Пресвете владичице наше Богородице у Влахерни.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-16',null,array[]::text[],'Свети мученик Јакинт. Празник Пресвете Богородице, у част Њене чудотворне иконе, назване „ Млекопитатељница“.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-17',null,array[]::text[],'Свети отац наш Андреј, Aрхиепископ Критски, Јерусалимљанин. И преподобна мати наша Марта, мајка преподобног Симеона Дивногорца. Свети свештеномученик Сава Горњокарловачки. И Света 73 свештеномученика горњокарловачка.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-18',null,array[]::text[],'Преподобни отац наш Атанасије Атонски. Обретење моштију Светог Сергија Радоњешког. Свети мученици Дабробосански.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-19',null,array[]::text[],'НЕДЕЉА СЕДМА ПО ПЕДЕСЕТНИЦИ. Преподобни отац наш Сисоје Велики.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-20',null,array[]::text[],'Преподобни отац наш Тома Малеин. И Света великомученица Недеља. И преподобни отац наш Акакије, из „ Лествице“ - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-21',null,array[]::text[],'Свети великомученик Прокопије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-22',null,array[]::text[],'Свети свештеномученик Панкратије, Епископ Тавроменски. Свети мученици Гламочки и Куленвакуфски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-23',null,array[]::text[],'Светих 45 мученика пострадалих у Никопољу Јерменском.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-24',null,array[]::text[],'Света великомученица Ефимија, Свехвална. И преподобни отац наш Михаило Малеин - њему се служба поје од 12.7.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-25',null,array[]::text[],'Празновање Пресвете Богородице у част њене чудотворне иконе, назване „ Тројеручица “. И Свети мученици Прокло и Иларије - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-26',null,array[]::text[],'НЕДЕЉА ОСМА ПО ПЕДЕСЕТНИЦИ. Недеља у којој се сећамо Светих и богоносних отаца наших првих шест Васељенских сабора. Сабор Светог архангела Гаврила. И преподобни отац наш Стефан Саваит - њима службу појати на повечерју. Сабор светих и преподобних отаца наших у манастиру Хиландару, на Светој Гори просијалих.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-27',null,array[]::text[],'Свети апостол Акила. Преподобни отац наш Никодим Светогорац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-28',null,array[]::text[],'Свети мученици Кирик и Јулита. Свети мученици Величко-горњеполимски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-29',null,array[]::text[],'Свети свештеномученик Атиноген, и десет ученика његових.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-30',null,array[]::text[],'Света великомученица Марина. И спомен Светих равноапостолних Седмочисленика, (Седморица) словенских просветитеља Методија, Кирила, Климента, Наума, Саве, Ангелара и Горазда - њима службу појати на повечерју. И Свети свештеномученици и мученици Ливањски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-07-31',null,array[]::text[],'Свети мученик Емилијан. И Свети мученик Јакинт и дружина његова.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-01',null,array[]::text[],'Свети и праведни Стефан Високи (Лазаревић), деспот српски. Преподобна мати наша Евгенија, у великој схими Ефросинија (пре монашења кнегиња српска Милица). И преподобна мати наша Макрина, сестра Св. Василија Великог - службу појати на повечерју. И преподобни отац наш Дије - њему службу појати на повечерју 20.7.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-02',null,array[]::text[],'НЕДЕЉА ДЕВЕТА ПО ПЕДЕСЕТНИЦИ. Свети и славни пророк Илија. И преподобни отац наш Дије - њему службу појати на повечерју од 19.7.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-03',null,array[]::text[],'Преподобни отац наш Симеон, Христа ради јуродиви и Јован, саподвижник његов. И Свети пророк Језекиљ. Свети свештеномученици гламочки Сима и Мирко.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-04',null,array[]::text[],'Света мироносица и равноапостолна Марија Магдалина. И Свети свештеномученик Фока.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-05',null,array[]::text[],'Свети мученици Трофим и Теофил и они с њима пострадали.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-06',null,array[]::text[],'Света мученица Христина. Свети мученици Пребиловачки и остали Херцеговачки мученици.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-07',null,array[]::text[],'Успеније Свете Ане, мајке Пресвете Богородице. И Свете жене Олимпијада и Евпраксија - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-08',null,array[]::text[],'Свети свештеномученик Ермолај и они са њиме пострадали. И Света мученица Параскева - њој службу појати на повечерју. И Свети отац наш Сава III Архиепископ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-09',null,array[]::text[],'НЕДЕЉА ДЕСЕТА ПО ПЕДЕСЕТНИЦИ. Свети великомученик и исцелитељ Пантелејмон. И Свети отац наш Климент, Архиепископ Охридски, Чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-10',null,array[]::text[],'Свети апостоли и ђакони Прохор, Никанор, Тимон и Пармен. Свети свештеномученкик Милош, Грковачко-црнолушки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-11',null,array[]::text[],'Свети мученик Калиник.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-12',null,array[]::text[],'Свети апостоли Сила, Силуан и они са њима. Преподобна мати наша Ангелина, бивша деспотица српска.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-13',null,array[]::text[],'Претпразништво Изношења Часног и Животворног Крста Господњег. Свети и праведни Евдоким.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-14',null,array[]::text[],'Празник Изношења Часног и Животворног Крста Господњег. Светих седам мученика Макавејских. И мајка њихова Соломонија и учитељ Елеазар.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-15',null,array[]::text[],'Пренос моштију Светог апостола, првомученика и архиђакона Стефана.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-16',null,array[]::text[],'НЕДЕЉА ЈЕДАНАЕСТА ПО ПЕДЕСЕТНИЦИ. Преподобни оци наши Исакије, Далмат и Фавст.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-17',null,array[]::text[],'Светих седам младића Ефеских.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-18',null,array[]::text[],'Претпразништво Преображења Господа нашега Исуса Христа. И Свети мученик Евсигније.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-19',null,array[]::text[],'СВЕТО ПРЕОБРАЖЕЊЕ ГОСПОДА И БОГА И СПАСА НАШЕГА ИСУСА ХРИСТА.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-20',null,array[]::text[],'Попразништво Преображења. Свети преподобномученик Дометије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-21',null,array[]::text[],'Попразништво Преображења. Свети Емилијан Исповедник, Епископ Кизички. И преподобни Зосим Тумански, Синаит. Преподобни Јаков (Арсовић).',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-22',null,array[]::text[],'Попразништво Преображења. Свети и свехвални апостол Матија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-23',null,array[]::text[],'НЕДЕЉА ДВАНАЕСТА ПО ПЕДЕСЕТНИЦИ. Попразништво Преображења. Свети мученик и архиђакон Лаврентије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-24',null,array[]::text[],'Попразништво Преображења. Света мученик и архиђакон Евпло.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-25',null,array[]::text[],'Попразништво Преображења. Свети мученици Фотије и Аникит. И пренос моштију преподобног оца нашег Максима Исповедника - службу појати од 13.8.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-26',null,array[]::text[],'Оданије Празника Преображење Господа, Бога и Спаса нашега Исуса Христа. Пренос моштију преподобног оца нашег Максима Исповедника - служба се поје 12.8.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-27',null,array[]::text[],'Претпразништво Успења Пресвете Богородице. И Свети пророк Михеј.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-28',null,array[]::text[],'УСПЕЊЕ ПРЕСВЕТЕ СЛАВНЕ ВЛАДИЧИЦЕ НАШЕ БОГОРОДИЦЕ И УВЕК ДЈЕВЕ МАРИЈЕ.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-29',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Пренос Светог Убруса са нерукотвореним ликом Господа и Бога и Спаситеља нашег Исуса Христа из Едесе у Цариград. Свети мученик Диомид - њему службу појати на повечерју. Преподобни отац наш Роман Ђуниски. Преподобни отац наш Рафаило Банатски, Хиландарац. Свети отац наш Евстатије II, Архиепископ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-30',null,array[]::text[],'НЕДЕЉА ТРИНАЕСТА ПО ПЕДЕСЕТНИЦИ. Попразништво Успења Пресвете Богородице. Свети мученик Мирон. И пренос моштију Светог Стефана Штиљановића.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-08-31',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Свети мученици Флор и Лавр. И Преподобни Јован Рилски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-01',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Свети мученик Андреј Стратилат, и са њиме 2593 мученика.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-02',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Свети пророк Самуило.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-03',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Свети апостол Тадеј. И Света мученица Васа, и њена деца. Свети преподобномученик Рафаило Шишатовачки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-04',null,array[]::text[],'Попразништво Успења Пресвете Богородице. Свети мученик Агатоник. И Свети мученик Луп - њему се служба поје од 23.8. И Свети свештеномученик Горазд, Епископ Чешки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-05',null,array[]::text[],'Оданије Празника Успења Пресвете Богородице. Свети свештеномученик Иринеј, Епископ Лионски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-06',null,array[]::text[],'НЕДЕЉА ЧЕТРНАЕСТА ПО ПЕДЕСЕТНИЦИ. Свети свештеномученик Евтихије, ученик Светог Јована Богослова.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-07',null,array[]::text[],'Враћање моштију Светог апостола Вартоломеја. И Свети апостол Тит.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-08',null,array[]::text[],'Свети мученици Адријан и Наталија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-09',null,array[]::text[],'Преподобни отац наш Пимен.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-10',null,array[]::text[],'Преподобни отац наш Мојсије Мурин.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-11',null,array[]::text[],'Усековање часне главе часног славног Пророка, Претече и Крститеља Јована.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-12',null,array[]::text[],'Свети цариградски патријарси Александар, Јован и Павле Нови. И пренос часних моштију Светог благоверног кнеза Александра Невског, у монаштву Алексија, из града Владимира у Петровград - службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-13',null,array[]::text[],'НЕДЕЉА ПЕТНАЕСТА ПО ПЕДЕСЕТНИЦИ. Полагање часног Појаса Пресвете владичице наше Богородице у Халкопатији - службу појати на повечерју. Сабор Светих српских просветитеља и учитеља. Свети мученици Јасеновачки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-14',null,array[]::text[],'Почетак Индикта, то јест новог лета. И преподобни отац наш Симеон Столпник и архимандрит. И преподобна Марта, матера његова. И Светих 40 жена.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-15',null,array[]::text[],'Свети мученик Мамант. И Свети Јован Постник, Патријарх Цариградски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-16',null,array[]::text[],'Свети свештеномученик Антим, Епископ Никомидијски. И Свети отац наш Јоаникије, Архиепископ и први Патријарх Српски. И преподобни Теоктист, служитељ Светог Ефтимија Великог – њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-17',null,array[]::text[],'Свети свештеномученик Вавила, Архиепископ Велике Антиохије. И пророк и боговидац Мојсије. И Свети свештеномученик Петар, Митрополит Дабробосански. Преподобни Стефан Троношки.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-18',null,array[]::text[],'Свети пророк Захарија и Света и праведна Јелисавета, родитељи Светог Јована, Пророка, Претече и Крститеља Господњег.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-19',null,array[]::text[],'Успомена чуда у Колоси у Хони Светог Архангела Михаила. Свети мученик Евдокије из Мелетине и са њим пострадали - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-20',null,array[]::text[],'НЕДЕЉА ШЕСНАЕСТА ПО ПЕДЕСЕТНИЦИ. Претпразништво Рођења Пресвете Богородице. И Свети мученик Созонт. Недеља пред Воздвижење (Уздизање) Часнога Крста.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-21',null,array[]::text[],'РОЂЕЊЕ ПРЕСВЕТЕ ВЛАДИЧИЦЕ НАШЕ БОГОРОДИЦЕ И УВЕК ДЈЕВЕ МАРИЈЕ.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-22',null,array[]::text[],'Попразништво Рођења Пресвете Богородице. Свети и праведни Јоаким и Ана. И Свети мученик Северијан - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-23',null,array[]::text[],'Попразништво Рођења Пресвете Богородице. Свете мученице Минодора, Митродора и Нимфодора.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-24',null,array[]::text[],'Попразништво Рођења Пресвете Богородице. Преподобна Теодора Александријска. И Свети свештеномученик Автоном.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-25',null,array[]::text[],'Оданије Празника Рођења Пресвете Богородице. Свети свештеномученик Автоном - њему се служба поје 11. овог месеца.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-26',null,array[]::text[],'Спомен освећења храма Светог Васкрсења Христа Бога нашега. Претпразништво Воздвижења ( Уздизања ) Часнога и Животворнога Крста. И Свети свештеномученик Корнилије Сотник (= Капетан ). Субота пред Воздвижење ( Узношење ) Часног Крста.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-27',null,array[]::text[],'НЕДЕЉА СЕДАМНАЕСТА ПО ПЕДЕСЕТНИЦИ. СВЕЧАСНО ВОЗДВИЖЕЊЕ (УЗДИЗАЊЕ) ЧАСНОГ И ЖИВОТВОРНОГ КРСТА.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-28',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Свети великомученик Никита. И обретење (проналазак) моштију Светог апостола, првомученика и архиђакона Стефана - њему службу појати на повечерју. Свети отац наш Јосиф Нови - Партошки, Митрополит Темишварски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-29',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Света и прехвална мученица Ефимија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-09-30',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Света Софија (Мудрост) и њене три кћери: Писта (Вера), Елпида (Нада) и Агапија (Љуба(в)).',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-01',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Свети отац наш Евменије, Епископ Гортински, Чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-02',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Свети мученици Трофим, Саватије и Доримедонт. Обретење моштију Светог Иринеја, Епископа Бачког, Исповедника вере и Светих мученика Бачких.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-03',null,array[]::text[],'Попразништво Воздвижења Часног Крста. Свети великомученик Евастатије и са њиме пострадали. Субота по Воздвижењу ( Узношењу ) Часног Крста.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-04',null,array[]::text[],'НЕДЕЉА ОСАМНАЕСТА ПО ПЕДЕСЕТНИЦИ. Оданије Празника Воздвижења (Узношења) Часног Крста. Свети апостол Кодрат у Магнивији - њему службу појати 22.9. Недеља по Воздвижењу (Уздизања) Часног Крста.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-05',null,array[]::text[],'Свети свештеномученик Фока (Синопски). И Свети апостол Кодрат у Магнивији - дан прослављања 21.9. И пророк Јона и преподобни Јона Презвитер, отац Теофана (писца канона) и Теодора Начертаног - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-06',null,array[]::text[],'Зачеће Светога Пророка, Претече и Крститеља Јована.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-07',null,array[]::text[],'Света првомученица и равноапостолна Текла. И преподобни отац наш Симон, бивши краљ Српски, Стефан Првовенчани. И Свети и благоверни Владислав, Краљ Српски. Преподобни Давид Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-08',null,array[]::text[],'Преподобна мати наша Ефросинија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-09',null,array[]::text[],'Престављење Светог Апостола и Јеванђелисте Јована Богослова.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-10',null,array[]::text[],'Свети мученик Калистрат и са њим пострадали.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-11',null,array[]::text[],'НЕДЕЉА ДЕВЕТНАЕСТА ПО ПЕДЕСЕТНИЦИ. Преподобни отац наш Харитон Исповедник. И Свети преподобномученици медљански, игуман Серафим, монаси Авакум и Мардарије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-12',null,array[]::text[],'Преподобни отац наш Киријак Отшелник.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-13',null,array[]::text[],'Свети свештеномученик Григорије, Епископ и просветитељ Велике Јерменије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-14',null,array[]::text[],'Покров Пресвете Богородице. Свети апостол Ананија, један од Седамдесеторице. И преподобни Роман Слаткопојац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-15',null,array[]::text[],'Свети свештеномученик Кипријан. И Света мученица Јустина. И Свети и блажени Андреј, Христа ради јуродиви - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-16',null,array[]::text[],'Свети свештеномученик Дионисије Ареопагит, Епископ Атински. Свети Пајсије Јањевац, Патријарх Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-17',null,array[]::text[],'Свети отац наш Јеротеј, Епископ Атински. И Свети и праведни кнез Стефан Штиљановић. Преподобна Јелисавета (Јелена Штиљановић).',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-18',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТА ПО ПЕДЕСЕТНИЦИ. Света мученица Харитина.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-19',null,array[]::text[],'Свети и свехвални апостол Тома.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-20',null,array[]::text[],'Свети и славни мученици Сергије и Вакхо.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-21',null,array[]::text[],'Преподобна мати наша Пелагија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-22',null,array[]::text[],'Свети и свехвални апостол Јаков Алфејев. И Свети и праведни Стефан Нови (Слепи), бивши деспот српски. И преподобни отац наш Андроник и супруга његова Атанасија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-23',null,array[]::text[],'Свети мученици Евлампије и Евлампија.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-24',null,array[]::text[],'Свети апостол Филип, један од седморице ђакона. И Свети Теофан Исповедник, Епископ Никејски, писац канона.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-25',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ПРВА ПО ПЕДЕСЕТНИЦИ. Спомен Светих отаца VII Васељенског Сабора. Свети мученици Пров, Тарах и Андроник – њима службу појати на повечерју. И Свети отац наш Козма Светоградски, писац канона, Епископ Мајумски. Празновање Пресвете Богородице, чудотворне Њене иконе, назване Јерусалимска. Спомен преподобног и богоносног оца нашег Симеона Новог Богослова.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-26',null,array[]::text[],'Свети мученици Карп и Папил. И Света великомученица Злата Мегленска. И Света мученица Босиљка.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-27',null,array[]::text[],'Преподобна мати наша Параскева. Свети мученици Назарије, Гервасије, Протасије и Келсије - њима службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-28',null,array[]::text[],'Преподобни отац наш Евтимије Нови. И Свети преподобномученик Лукијан, презвитер Велике Антиохије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-29',null,array[]::text[],'Свети мученик Лонгин Сотник (= Капетан ), / који стајаше / при Крсту Господњем.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-30',null,array[]::text[],'Свети пророк Осија. И Свети преподобномученик Андреј са Крита.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-10-31',null,array[]::text[],'Свети апостол и јеванђелист Лука. И Свети отац наш Петар I Митрополит црногорски, чудотворац Цетињски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-01',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ДРУГА ПО ПЕДЕСЕТНИЦИ. Свети пророк Јоил. И Свети мученик Уар. Преподобни и богоносни отац наш Прохор Пчињски. Пренос моштију преподобног Јована Рилског.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-02',null,array[]::text[],'Свети великомученик Артемије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-03',null,array[]::text[],'Преподобни отац наш Иларион Велики. И преподобни исповедник Висарион Ердељски. И Свети Иларион Мегленски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-04',null,array[]::text[],'Свети равноапостолни Аверкије, Епископ Јерапољски, Чудотворац. И Светих седам ( мученика ) младића у Ефесу.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-05',null,array[]::text[],'Свети апостол Јаков, брат Божији.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-06',null,array[]::text[],'Свети мученик Арета и они са њиме пострадали.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-07',null,array[]::text[],'Свети мученици и нотари Маркијан и Мартиријан.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-08',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ТРЕЋА ПО ПЕДЕСЕТНИЦИ. Свети и славни великомученик Димитрије Мироточиви ( Солунски ). И спомен великог и страшног земљотреса у Цариграду.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-09',null,array[]::text[],'Свети мученик Нестор.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-10',null,array[]::text[],'Свети мученици Терентије и Неонила. И Свети отац наш Арсеније, Архиепископ Српски. И преподобни Стефан Саваит, писац канона - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-11',null,array[]::text[],'Света преподобномученица Анастасија Римљанка. И преподобни отац наш Аврамије Затворник.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-12',null,array[]::text[],'Свети мученици Зиновија и Зиновије. Свети и благочестиви, велики и богоносни Стефан Милутин, Краљ Српски. И преподобни отац наш Теоктист, бивши Драгутин, краљ Српски. И преподобна Јелисавета, бивша краљица српска Јелена ( Анжујска ). Свети Варнава Исповедник, Епископ Хвостански.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-13',null,array[]::text[],'Свети апостоли Стахије, Амплије, Урван и остали. И Свети мученик Епимах.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-14',null,array[]::text[],'Свети бесребреници и чудотворци Козма и Дамјан, родом из Асије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-15',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ЧЕТВРТА ПО ПЕДЕСЕТНИЦИ. Свети мученици Акиндин, Афтоније, Пигасије, Елпидифор и Анембодист.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-16',null,array[]::text[],'Свети мученици Акепсим, Јосиф и Аитал. И освећење цркве Светог мученика Георгија у Лиди, где је положено његово тело.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-17',null,array[]::text[],'Преподобни отац наш Јоаникије Велики. И Свети ( свештено ) мученици Никандар, Епископ Мирски и Ермеј Презвитер. Свети оци наши, и све српски просветитељи и учитељи Свети Сава, Арсеније и Максим.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-18',null,array[]::text[],'Свети мученици Галактион и Епистима.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-19',null,array[]::text[],'Свети отац наш Павле, Архиепископ Цариградски, Исповедник.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-20',null,array[]::text[],'Света тридесет и три мученика у Мелитини. И преподобни отац наш Лазар Нови, Чудотворац, који је просијао на Галисијској Гори.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-21',null,array[]::text[],'Сабор Светог Архистратига Михаила и осталих бестелесних сила.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-22',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ПЕТА ПО ПЕДЕСЕТНИЦИ. Свети мученици Онисифор и Порфирије. И преподобна мати наша Матрона. И преподобна Теоктиста из Лезвије - њој службу појати на повечерју. Преподобни отац наш Симеон Логотет ( Метафраст ) Свети отац наш Нектарије Егински, Чудотворац, Епископ Пентапољски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-23',null,array[]::text[],'Свети апостоли Ераст, Олимп, Родион и они с њима.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-24',null,array[]::text[],'Свети мученици Мина, Виктор и Викентије. И преподобни отац наш и исповедник Теодор Студит - њему службу појати на повечерју. Свети великомученик Стефан Дечански, Краљ Српски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-25',null,array[]::text[],'Свети отац наш Јован Милостиви, Архиепископ Александријски. И преподобни отац наш Нил.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-26',null,array[]::text[],'Свети отац наш Јован, Архиепископ Цариградски, Златоусти.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-27',null,array[]::text[],'Свети и свехвални апостол Филип. И Свети отац наш Григорије Палама, Архиепископ Солунски - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-28',null,array[]::text[],'Почетак Божићног поста. Свети мученици Гурије, Самон и Авив.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-29',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ШЕСТА ПО ПЕДЕСЕТНИЦИ. Свети Апостол и Јеванђелист Матеј.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-11-30',null,array[]::text[],'Свети отац наш Григорије, Епископ Неокесаријски, Чудотворац. Преподобни Севастијан Џексонски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-01',null,array[]::text[],'Свети мученик Платон. И Свети мученик Роман.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-02',null,array[]::text[],'Свети пророк Авдија. И Свети мученик Варлаам. Преподобни и богоносни оци наши Варлаам и Јоасаф Царевић, Индијски. Преподобни Порфирије Кавсокаливит.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-03',null,array[]::text[],'Претпразништво Ваведења Пресвете Богородице. И преподобни Григорије Декаполит. И Свети отац наш Прокло, Архиепископ Цариградски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-04',null,array[]::text[],'УВОЂЕЊЕ У ХРАМ ПРЕСВЕТЕ ВЛАДИЧИЦЕ НАШЕ БОГОРОДИЦЕ.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-05',null,array[]::text[],'Попразништво Ваведења Пресвете Богородице. Свети апостол Филимон и они с њиме. Преподобни и богоносни оци наши Симеон и Сава, ктитори свештене обитељи Хиландарске.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-06',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ СЕДМА ПО ПЕДЕСЕТНИЦИ. Попразништво Ваведења Пресвете Богородице. Свети отац наш Амфилохије, Епископ Иконијски. И Свети отац наш Григорије, Епископ Акрагански - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-07',null,array[]::text[],'Попразништво Ваведења Пресвете Богородице. Света великомученица Екатерина. И Свети великомученик Меркурије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-08',null,array[]::text[],'Оданије Празника Увођења у Храм Пресвете Владичице наше Богородице. Свети отац наш, свештеномученик Климент, Папа Римски. И Свети отац наш, свештеномученик Петар Александријски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-09',null,array[]::text[],'Преподобни отац наш Алипије Столпник. Освећење храма великомученика Георгија који је у Кијеву пред вратима Свете Софије.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-10',null,array[]::text[],'Свети мученик Јаков Персенин ( Персијанац ). И преподобни отац наш Паладије - њему службу појати на повечерју.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-11',null,array[]::text[],'Свети преподобномученик Стефан Нови. И Свети мученик Иринарх – њему службу појати на повечерју. И Свети мученик Христо.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-12',null,array[]::text[],'Свети мученик Парамон. И Свети мученик Филумен - иако се помиње у Типику, у Минејима нема службу. И преподобни отац наш Акакије Синајски - њему службу појати на повечерју. Свети Мардарије, Епископ Америчко-канадски.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-13',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ОСМА ПО ПЕДЕСЕТНИЦИ. Свети и свехвални Апостол Андреј Првозвани.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-14',null,array[]::text[],'Свети пророк Наум.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-15',null,array[]::text[],'Свети пророк Авакум. И Свети и блажени Урош Пети, Цар Српски. И преподобни отац наш Јоаникије Девички, Чудотворац.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-16',null,array[]::text[],'Свети пророк Софоније.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-17',null,array[]::text[],'Света великомученица Варвара. И Преподобни отац наш Јован Дамаскин.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-18',null,array[]::text[],'Преподобни отац наш Сава Освећени.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-19',null,array[]::text[],'Свети отац наш Николај, Архиепископ Мире Ликијске.',null,null,'Српска Православна Црква, Типик 2026',true),
('RS','sr','rs-serbian-orthodox-church','2026-12-20',null,array[]::text[],'НЕДЕЉА ДВАДЕСЕТ ДЕВЕТА ПО ПЕДЕСЕТНИЦИ. Свети отац наш Амвросије, Епископ Медиолански (=Милански). И преподобни и богоносни отац наш Григорије Ћутљиви, Горњачки, Синаит.',null,null,'Српска Православна Црква, Типик 2026',true),
